const a=$input.all().map(i=>i.json).filter(x=>x&&Object.keys(x).length);
if(a.some(x=>x.error))return [{json:{readable:false,activeCount:0,reason:'ESPOCRM_UNAVAILABLE'}}];
const keys=new Set();
for(const c of a){if(!c.id||keys.has(c.id))throw new Error('DUPLICATE_ESPO_CAMPAIGN_ID');keys.add(c.id);}
return [{json:{readable:true,count:a.length,activeCount:a.filter(x=>x.status==='Active').length,
 chatwootConfigured:a.filter(x=>String(x.ageProvider||'').includes('Chatwoot')).length}}];

const a=$input.all().map(i=>i.json).filter(x=>x&&Object.keys(x).length);
if(a.some(x=>x.error))return [{json:{readable:false,reason:'CHATWOOT_UNAVAILABLE'}}];
const keys=new Set();
for(const c of a){const id=Number(c.id);if(!Number.isSafeInteger(id)||keys.has(id))throw new Error('INVALID_OR_DUPLICATE_CHATWOOT_ID');keys.add(id);}
return [{json:{readable:true,count:a.length,nativeWhatsApp:a.filter(c=>c.campaign_type==='one_off'&&c.inbox?.channel_type==='Channel::Whatsapp').length}}];

// Comprehensive dry-run controls. Independent of user-editable Data Tables, there is NEVER a send path.
const crm=$('Count Espo Campaigns').first().json;
const provider=$('Count Native Chatwoot Campaigns').first().json;
const raw=$input.all().map(i=>i.json).filter(x=>x&&Object.keys(x).length);
const reasons=[];
if(!crm.readable)reasons.push('ESPOCRM_NOT_READABLE');
if(!provider.readable)reasons.push('CHATWOOT_NOT_READABLE');
if(raw.some(x=>x.error))reasons.push('N8N_DATA_TABLE_UNAVAILABLE');
if(!raw.length)reasons.push('NO_PORTFOLIO_RECORDS');
if(raw.length>50)reasons.push('PORTFOLIO_CONTROL_TOO_MANY_ROWS');
const seen=new Set(),now=Date.now(),portfolios=[];
function recent(t,h) { const ms=Date.parse(t); return Number.isFinite(ms)&&ms<=now&&now-ms<=h*3600000; }
for(const x of raw.filter(x=>!x.error).slice(0,50)){
  const id=String(x.portfolioId||'').trim(),holds=[];
  if(!id||seen.has(id))holds.push('MISSING_OR_DUPLICATE_PORTFOLIO_ID');
  seen.add(id);
  if(x.masterSendingEnabled!==true)holds.push('MASTER_DISABLED');
  if(x.operatorLiveApproved!==true)holds.push('OPERATOR_APPROVAL_NOT_VERIFIED');
  if(x.providerAnalyticsVerified!==true)holds.push('ANALYTICS_NOT_VERIFIED');
  if(x.accountHealthVerified!==true)holds.push('ACCOUNT_HEALTH_NOT_VERIFIED');
  if(!Number.isSafeInteger(x.messagingTier)||x.messagingTier<=0||!recent(x.tierVerifiedAt,24))holds.push('TIER_UNKNOWN_OR_STALE');
  if(!recent(x.qualityVerifiedAt,24))holds.push('QUALITY_UNKNOWN_OR_STALE');
  if(x.externalUsageUnknown!==false||!Number.isSafeInteger(x.externalUnique24h)||x.externalUnique24h<0||
    !recent(x.externalUsageVerifiedAt,24))holds.push('EXTERNAL_USAGE_UNKNOWN_OR_STALE');
  if(x.unresolvedCycle!==false||String(x.activeCycleId||'').trim())holds.push('UNRESOLVED_CYCLE');
  if(x.priorCycleHistoryVerified!==true)holds.push('PRIOR_CYCLE_HISTORY_NOT_VERIFIED');
  if(x.lastVerifiedBatchCompletedAt){
    const ms=Date.parse(x.lastVerifiedBatchCompletedAt);
    if(!Number.isFinite(ms)||now-ms<26*3600000)holds.push('GLOBAL_26_HOUR_GAP_OR_INVALID_COMPLETION');
  }
  if(!Number.isSafeInteger(x.rollingReserved24h)||x.rollingReserved24h<0)holds.push('RESERVATION_LEDGER_NOT_VERIFIED');
  const capacity=Number.isSafeInteger(x.messagingTier)&&Number.isSafeInteger(x.externalUnique24h)&&Number.isSafeInteger(x.rollingReserved24h)?
    Math.max(0,x.messagingTier-x.externalUnique24h-x.rollingReserved24h):null;
  if(capacity===0)holds.push('NO_RECORDED_HEADROOM');
  holds.push('DATA_TABLE_IS_NOT_ATOMIC_SEND_AUTHORITY','META_LIVE_CAPACITY_NOT_INDEPENDENTLY_PROVEN');
  portfolios.push({portfolioId:id||null,holds,recordedTier:x.messagingTier??null,estimatedHeadroom:capacity});
}
return [{json:{checkedAt:new Date().toISOString(),mode:'DRY_RUN',decision:'HOLD',
 espoCampaignCount:crm.count??0,activeEspoCampaigns:crm.activeCount??0,
 chatwootCampaignCount:provider.count??0,portfolios,
 reasons:[...new Set([...reasons,'RECIPIENT_CONSENT_AND_CRM_RETRY_NOT_VERIFIED','IMMUTABLE_CHATWOOT_BATCH_NOT_VERIFIED','NO_PRODUCTION_SENDING_GATE'])],
 canSend:false,createdCampaigns:0,crmEventsWritten:0}}];
